list_tax_country_taxes.code:
use WebCommander\Sdk\Resources\TaxCountryTaxes\TaxCountryTaxes;

$response = TaxCountryTaxes::listTaxCountryTaxes($client, ['limit' => 20]);

foreach ($response->map['country_taxes'] as $countryTax) {
    echo $countryTax['id'], ' ', $countryTax['name'], ' ', $countryTax['rate_display'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' country taxes in total', PHP_EOL;

get_tax_country_tax.code:
use WebCommander\Sdk\Resources\TaxCountryTaxes\TaxCountryTaxes;

$response = TaxCountryTaxes::getTaxCountryTax($client, 4);

$countryTax = $response->map['country_tax'];
echo $countryTax['name'], ' ', $countryTax['rate_display'], PHP_EOL;
foreach ($countryTax['state_rules'] as $rule) {
    echo 'state rule ', $rule['id'], ' ', $rule['tax_rule'], ' ', $rule['effective_tax_rate'], PHP_EOL;
}
